<?php
declare(strict_types=1);

function delivery_zone_response(array $z): array { $min=(int)$z['estimated_days_min'];$max=(int)$z['estimated_days_max'];return ['id'=>(int)$z['id'],'name'=>$z['name'],'city'=>$z['city'],'fee'=>(int)$z['fee'],'estimatedDaysMin'=>$min,'estimatedDaysMax'=>$max,'estimatedDelivery'=>$min===$max?"$min jour".($min>1?'s':''):"$min-$max jours",'active'=>(bool)$z['active']]; }
function discount_response(array $d): array { return ['id'=>(int)$d['id'],'code'=>$d['code'],'type'=>$d['type'],'value'=>(int)$d['value'],'active'=>(bool)$d['active'],'validFrom'=>$d['valid_from'],'validUntil'=>$d['valid_until'],'minOrderAmount'=>$d['min_order_amount']===null?null:(int)$d['min_order_amount'],'maxUses'=>$d['max_uses']===null?null:(int)$d['max_uses'],'usedCount'=>(int)$d['used_count']]; }
function valid_discount(?string $code,int $subtotal): ?array { if(!$code)return null;$q=db()->prepare('SELECT * FROM discount_codes WHERE UPPER(code)=UPPER(?) AND active=1 AND (valid_from IS NULL OR valid_from<=NOW()) AND (valid_until IS NULL OR valid_until>=NOW()) AND (max_uses IS NULL OR used_count<max_uses)');$q->execute([$code]);$d=$q->fetch();if(!$d)return null;if($d['min_order_amount']!==null&&$subtotal<(int)$d['min_order_amount'])return null;return $d; }
function discount_amount(array $d,int $subtotal): int { return $d['type']==='PERCENTAGE'?min($subtotal, max(0, (int)floor($subtotal * min(100, max(0, (int)$d['value'])) / 100 / 5) * 5)):min($subtotal,(int)$d['value']); }

function cart_token(): ?string { return $_SERVER['HTTP_X_CART_TOKEN']??null; }
function cart_id(bool $create=false): ?int { $token=cart_token();if($token){$q=db()->prepare('SELECT id FROM carts WHERE token=?');$q->execute([$token]);$id=$q->fetchColumn();if($id)return (int)$id;}if(!$create)fail(404,'CART_NOT_FOUND','Panier introuvable.');$token=bin2hex(random_bytes(32));$u=current_user(false);db()->prepare('INSERT INTO carts(token,user_id) VALUES(?,?)')->execute([$token,$u['id']??null]);$_SERVER['HTTP_X_CART_TOKEN']=$token;header('X-Cart-Token: '.$token);return (int)db()->lastInsertId(); }
function cart_response(int $id): array { $q=db()->prepare('SELECT token FROM carts WHERE id=?');$q->execute([$id]);$token=$q->fetchColumn();$q=db()->prepare('SELECT ci.quantity,v.id variant_id,v.format,v.stock,v.price,v.promo_price,p.id product_id,p.name,p.image_url FROM cart_items ci JOIN product_variants v ON v.id=ci.variant_id JOIN products p ON p.id=v.product_id WHERE ci.cart_id=?');$q->execute([$id]);$items=[];$subtotal=0;$count=0;foreach($q->fetchAll() as $r){$price=(int)($r['promo_price']?:$r['price']);$line=$price*(int)$r['quantity'];$subtotal+=$line;$count+=(int)$r['quantity'];$items[]=['variantId'=>(int)$r['variant_id'],'productId'=>(int)$r['product_id'],'productName'=>$r['name'],'format'=>$r['format'],'imageUrl'=>$r['image_url'],'quantity'=>(int)$r['quantity'],'unitPrice'=>$price,'lineTotal'=>$line,'availableStock'=>(int)$r['stock']];}return ['token'=>$token,'currency'=>'EUR','subtotal'=>$subtotal,'totalItems'=>$count,'items'=>$items]; }
function add_cart_item(): never { $b=json_body();require_fields($b,['variantId','quantity']);$qty=(int)$b['quantity'];if(filter_var($b['quantity'],FILTER_VALIDATE_INT)===false||$qty<1||$qty>1000)fail(422,'VALIDATION_ERROR','Quantite invalide.');$q=db()->prepare('SELECT v.stock FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id=? AND p.active=1');$q->execute([(int)$b['variantId']]);$stock=$q->fetchColumn();if($stock===false)fail(404,'NOT_FOUND','Variante introuvable.');$id=cart_id(true);$pdo=db();$pdo->beginTransaction();try{$lock=$pdo->prepare('SELECT id FROM carts WHERE id=? FOR UPDATE');$lock->execute([$id]);if(!$lock->fetchColumn())fail(409,'CART_CHANGED','Panier modifie.');$q=db()->prepare('SELECT quantity FROM cart_items WHERE cart_id=? AND variant_id=?');$q->execute([$id,(int)$b['variantId']]);$existing=(int)($q->fetchColumn()?:0);if($existing+$qty>(int)$stock)fail(409,'INSUFFICIENT_STOCK','Stock insuffisant.');db()->prepare('INSERT INTO cart_items(cart_id,variant_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)')->execute([$id,(int)$b['variantId'],$qty]);$result=cart_response($id);$pdo->commit();respond($result);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }

function order_response(array $o): array { $q=db()->prepare('SELECT variant_id,product_name,format,unit_price,quantity,line_total FROM order_items WHERE order_id=?');$q->execute([(int)$o['id']]);$items=array_map(fn($i)=>['variantId'=>(int)$i['variant_id'],'productName'=>$i['product_name'],'format'=>$i['format'],'unitPrice'=>(int)$i['unit_price'],'quantity'=>(int)$i['quantity'],'lineTotal'=>(int)$i['line_total']],$q->fetchAll());$min=$o['estimated_days_min']??null;$max=$o['estimated_days_max']??null;$estimate=$min===null?null:((int)$min===(int)$max?"$min jour".($min>1?'s':''):"$min-$max jours");return ['orderNumber'=>$o['order_number'],'status'=>$o['status'],'items'=>$items,'subtotal'=>(int)$o['subtotal'],'deliveryFee'=>(int)$o['delivery_fee'],'discountCode'=>$o['discount_code'],'discountAmount'=>(int)$o['discount_amount'],'total'=>(int)$o['total'],'currency'=>$o['currency'],'contactEmail'=>$o['contact_email'],'contactPhone'=>$o['contact_phone'],'recipientName'=>$o['recipient_name'],'city'=>$o['city'],'commune'=>$o['commune'],'addressLine'=>$o['address_line'],'country'=>$o['country'],'deliveryMethod'=>$o['delivery_method'],'deliveryZoneName'=>$o['zone_name']??null,'estimatedDelivery'=>$estimate,'trackingNote'=>$o['tracking_note'],'createdAt'=>date(DATE_ATOM,strtotime($o['created_at']))]; }
function find_order(string $number,bool $admin=false): array { $q=db()->prepare('SELECT o.*,z.name zone_name,z.estimated_days_min,z.estimated_days_max FROM orders o LEFT JOIN delivery_zones z ON z.id=o.delivery_zone_id WHERE o.order_number=?');$q->execute([$number]);$o=$q->fetch();if(!$o)fail(404,'NOT_FOUND','Commande introuvable.');if(!$admin){$u=current_user(false);$owned=$u&&$o['user_id']!==null&&(int)$o['user_id']===(int)$u['id'];$token=(string)($_SERVER['HTTP_X_ORDER_TOKEN']??'');if(!$owned&&!hash_equals(order_access_token($o),$token))fail(404,'NOT_FOUND','Commande introuvable.');}return $o; }
function create_order(): never { $b=json_body();require_fields($b,['cartToken','contactEmail','recipientName','phone','city','addressLine','deliveryMethod']);validate_checkout($b);$key=(string)($_SERVER['HTTP_IDEMPOTENCY_KEY']??'');if(!preg_match('/^[a-f0-9]{32,64}$/',$key))fail(422,'IDEMPOTENCY_REQUIRED','Identifiant de commande obligatoire.');global $config;$number='KIC-'.strtoupper(substr(hash_hmac('sha256','checkout:'.$key,$config['app_key']),0,24));$existing=checkout_existing($number);if($existing)respond($existing);$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id FROM carts WHERE token=? FOR UPDATE');$q->execute([$b['cartToken']]);$cart=(int)$q->fetchColumn();if(!$cart)fail(422,'CART_EMPTY','Votre panier est vide.');$pdo->prepare('SELECT v.id FROM product_variants v JOIN cart_items ci ON ci.variant_id=v.id WHERE ci.cart_id=? ORDER BY v.id FOR UPDATE')->execute([$cart]);$c=cart_response($cart);if(!$c['items'])fail(422,'CART_EMPTY','Votre panier est vide.');$zone=null;$fee=0;if(($b['deliveryMethod']??'DELIVERY')==='DELIVERY'){if(empty($b['deliveryZoneId']))fail(422,'VALIDATION_ERROR','Zone de livraison obligatoire.');$q=db()->prepare('SELECT * FROM delivery_zones WHERE id=? AND active=1');$q->execute([(int)$b['deliveryZoneId']]);$zone=$q->fetch();if(!$zone)fail(422,'INVALID_DELIVERY_ZONE','Zone de livraison invalide.');$fee=(int)$zone['fee'];}$discount=valid_discount($b['discountCode']??null,$c['subtotal']);$discountValue=$discount?discount_amount($discount,$c['subtotal']):0;$total=max(0,$c['subtotal']+$fee-$discountValue);$u=current_user(false);$q=$pdo->prepare('INSERT INTO orders(user_id,subtotal,delivery_fee,discount_code,discount_amount,total,contact_email,contact_phone,recipient_name,city,commune,address_line,country,delivery_method,delivery_zone_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$u['id']??null,$c['subtotal'],$fee,$discount['code']??null,$discountValue,$total,strtolower($b['contactEmail']),$b['phone'],$b['recipientName'],$b['city'],$b['commune']??null,$b['addressLine'],$b['country']??'France',$b['deliveryMethod'],$zone['id']??null]);$id=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE orders SET order_number=? WHERE id=?')->execute([$number,$id]);foreach($c['items'] as $i){$updated=$pdo->prepare('UPDATE product_variants SET stock=stock-? WHERE id=? AND stock>=? AND EXISTS(SELECT 1 FROM products p WHERE p.id=product_variants.product_id AND p.active=1)');$updated->execute([$i['quantity'],$i['variantId'],$i['quantity']]);if(!$updated->rowCount())fail(409,'INSUFFICIENT_STOCK','Le stock a changé.');$pdo->prepare('INSERT INTO order_items(order_id,variant_id,product_name,format,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?,?)')->execute([$id,$i['variantId'],$i['productName'],$i['format'],$i['unitPrice'],$i['quantity'],$i['lineTotal']]);}if($discount){$usage=$pdo->prepare('UPDATE discount_codes SET used_count=used_count+1 WHERE id=? AND (max_uses IS NULL OR used_count<max_uses)');$usage->execute([$discount['id']]);if(!$usage->rowCount())fail(409,'DISCOUNT_EXHAUSTED','Code promotionnel épuisé.');}$pdo->prepare('DELETE FROM carts WHERE id=?')->execute([$cart]);$pdo->commit();$created=find_order($number,true);respond(array_merge(order_response($created),['accessToken'=>order_access_token($created)]),201);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if($e instanceof PDOException&&(int)($e->errorInfo[1]??0)===1062){$existing=checkout_existing($number);if($existing)respond($existing);}throw $e;} }
